+// Configuración del conector ERP: ERP_TIMEOUT_MS (ms, entero positivo); 5000 si no está definida.
+export function configuracionErp(env = process.env) {
+  const crudo = env.ERP_TIMEOUT_MS;
+  if (crudo === undefined) return { timeoutMs: 5000 };
+  const texto = String(crudo).trim();
+  if (!/^[1-9]\d*$/.test(texto) || !Number.isSafeInteger(Number(texto)))
+    throw new RangeError(`ERP_TIMEOUT_MS inválido: debe ser un entero positivo en milisegundos (recibido: ${crudo})`);
+  return { timeoutMs: Number(texto) };
+}
